            if (!parsed) {
                return { valid: false, message: 'Invalid SAML request format' };
            }
            return { valid: true, data: parsed };
        } catch (error) {
            console.error('[SAML Service] SAML request validation failed:', error.message);
            return { valid: false, message: error.message };
