const XMLBuilder = require('./xmlBuilder');
const XMLSigner = require('./xmlSigner');

class ResponseBuilder {
    constructor(config) {
        this.issuer = config.issuer;
        this.certificate = config.certificate;
        this.privateKey = config.privateKey;
        this.signer = new XMLSigner(this.privateKey, this.certificate);
    }

    buildLoginResponse(options) {
        const {
            inResponseTo,
            destination,
            nameID,
            nameIDFormat = 'urn:oasis:names:tc:SAML:1.1:nameid-format:unspecified',
            attributes = [],
            sessionIndex,
            audience
        } = options;

        const responseID = XMLBuilder.generateID();
        const assertionID = XMLBuilder.generateID();
        const issueInstant = XMLBuilder.getCurrentTimestamp();
        const notBefore = issueInstant;
        const notOnOrAfter = XMLBuilder.getFutureTimestamp(5);
        const subjectNotOnOrAfter = XMLBuilder.getFutureTimestamp(5);
        const finalSessionIndex = sessionIndex || XMLBuilder.generateID();

        const responseWithoutAssertion = XMLBuilder.buildResponseWithoutAssertion({
            responseID,
            issueInstant,
            destination,
            issuer: this.issuer,
            inResponseTo,
            statusCode: 'urn:oasis:names:tc:SAML:2.0:status:Success'
        });

        const assertion = XMLBuilder.buildAssertion({
            assertionID,
            issueInstant,
            issuer: this.issuer,
            nameID,
            nameIDFormat,
            recipient: destination,
            audience: audience || destination,
            inResponseTo,
            sessionIndex: finalSessionIndex,
            attributes,
            notBefore,
            notOnOrAfter,
            subjectNotOnOrAfter
        });

        const signedAssertion = this.signer.signAssertion(assertion, assertionID);

        const signedResponse = this.signer.signResponse(
            responseWithoutAssertion,
            responseID,
            signedAssertion
        );

        return signedResponse;
    }

    buildLogoutResponse(options) {
        const {
            inResponseTo,
            destination,
            statusCode = 'urn:oasis:names:tc:SAML:2.0:status:Success'
        } = options;

        const responseID = XMLBuilder.generateID();
        const issueInstant = XMLBuilder.getCurrentTimestamp();

        return XMLBuilder.buildLogoutResponse({
            responseID,
            issueInstant,
            destination,
            issuer: this.issuer,
            inResponseTo,
            statusCode
        });
    }

    buildMetadata(options) {
        const {
            entityID,
            ssoLocation,
            sloLocation,
            nameIDFormats
        } = options;

        return XMLBuilder.buildMetadata({
            entityID: entityID || this.issuer,
            certificate: this.certificate,
            ssoLocation,
            sloLocation,
            nameIDFormats
        });
    }

    static encodeResponse(xml) {
        return Buffer.from(xml, 'utf8').toString('base64');
    }
}

module.exports = ResponseBuilder;

const { SignedXml } = require('xml-crypto');

class XMLSigner {
    constructor(privateKey, certificate) {
        this.privateKey = privateKey;
        this.certificate = certificate;
    }

    signAssertion(assertionXml, assertionID) {
        const xml = assertionXml.replace(/<\?xml[^?]*\?>\s*/g, '');

        const sig = new SignedXml();
        sig.privateKey = this.privateKey;

        sig.addReference({
            xpath: `//*[@ID="${assertionID}"]`,
            transforms: [
                'http://www.w3.org/2000/09/xmldsig#enveloped-signature',
                'http://www.w3.org/2001/10/xml-exc-c14n#'
            ],
            digestAlgorithm: 'http://www.w3.org/2001/04/xmlenc#sha256'
        });

        sig.canonicalizationAlgorithm = 'http://www.w3.org/2001/10/xml-exc-c14n#';
        sig.signatureAlgorithm = 'http://www.w3.org/2001/04/xmldsig-more#rsa-sha256';

        sig.keyInfoProvider = {
            getKeyInfo: () => {
                const certBody = this.certificate
                    .replace(/-----BEGIN CERTIFICATE-----/, '')
                    .replace(/-----END CERTIFICATE-----/, '')
                    .replace(/\s/g, '');

                return '<X509Data><X509Certificate>' + certBody + '</X509Certificate></X509Data>';
            }
        };

        sig.computeSignature(xml, {
            location: { reference: "//*[local-name(.)='Issuer']", action: 'after' }
        });

        return sig.getSignedXml();
    }

    signResponse(responseXml, responseID, signedAssertion) {
        const statusCloseTag = '</samlp:Status>';
        const insertPos = responseXml.indexOf(statusCloseTag);

        if (insertPos === -1) {
            throw new Error('Cannot find Status element');
        }

        const beforeAssertion = responseXml.substring(0, insertPos + statusCloseTag.length);
        const afterAssertion = responseXml.substring(insertPos + statusCloseTag.length);

        return beforeAssertion + signedAssertion + afterAssertion;
    }
}

module.exports = XMLSigner;

