            slo_services = idp_descriptor.xpath(
                f'.//md:SingleLogoutService[@Binding="{binding_uri}"]',
                namespaces=self.NAMESPACES
            )

            if slo_services:
                return slo_services[0].get('Location')

            slo_services = idp_descriptor.xpath(
