                namespaces=self.NAMESPACES
            )

            if slo_services:
                return slo_services[0].get('Location')

            return None
        except Exception:
            return None

    def get_idp_certificates(self):
        try:
            if self.document is None:
                return []

            certificates = []

            cert_nodes = self.document.xpath(
                '//ds:X509Certificate',
                namespaces=self.NAMESPACES
            )

